import React, { useState } from "react";
import SidebarTeacher from "../components/SidebarTeacher";
import axiosInstance from "../api/axios";
import "../global.css";

export default function SubjectMarks() {
  const [usn, setUsn] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [student, setStudent] = useState(null);
  const [marks, setMarks] = useState([]);

  const searchByUsn = async () => {
    setError("");
    setLoading(true);
    setStudent(null);
    setMarks([]);
    try {
      const res = await axiosInstance.get(`/marks/by-usn`, { params: { usn } });
      setStudent(res.data.student);
      setMarks(res.data.marks);
    } catch (e) {
      setError(e.response?.data?.message || "Failed to fetch marks");
    } finally {
      setLoading(false);
    }
  };

  const downloadPdf = async () => {
    try {
      const { default: jsPDF } = await import("jspdf");

      const doc = new jsPDF();
      doc.text(`Marks Report - ${student?.name || usn}`, 14, 16);

      // Header
      const startY = 24;
      let y = startY;
      doc.setFont(undefined, 'bold');
      doc.text('Subject', 14, y);
      doc.text('Category', 70, y);
      doc.text('Marks', 120, y);
      doc.text('Status', 160, y);
      doc.setFont(undefined, 'normal');
      y += 6;

      // Rows
      marks.forEach((m) => {
        doc.text(String(m.subject || ''), 14, y);
        doc.text(String(m.category || ''), 70, y);
        doc.text(String(m.marks ?? ''), 120, y);
        doc.text(String(m.status || '-'), 160, y);
        y += 6;
        if (y > 280) {
          doc.addPage();
          y = 20;
        }
      });

      doc.save(`${student?.name || usn}-marks.pdf`);
    } catch (_) {
      window.print();
    }
  };

  return (
    <div className="dashboard-flex">
      <SidebarTeacher active="View Marks" />

      <main className="dashboard-main">
        <header className="dashboard-header-row">
          <div>
            <h1 className="dashboard-title">View Marks</h1>
            <p className="dashboard-subtitle">Search student marks by USN and download PDF.</p>
          </div>
        </header>

        <section className="entermarks-form-block" style={{ padding: 16 }}>
          <div className="entermarks-form-row">
            <input
              value={usn}
              onChange={e => setUsn(e.target.value)}
              placeholder="Enter Student USN"
              style={{ flex: 1 }}
            />
            <button className="entermarks-save-btn" onClick={searchByUsn} disabled={!usn || loading}>
              {loading ? 'Searching...' : 'Search'}
            </button>
            {student && (
              <button className="entermarks-save-btn" onClick={downloadPdf}>
                <i className="fa-solid fa-file-arrow-down"></i> Download PDF
              </button>
            )}
          </div>

          {error && <div className="error-message" style={{ marginTop: 12 }}>{error}</div>}

          {student && (
            <div style={{ marginTop: 16 }}>
              <div className="muted">Student: <b>{student.name}</b> ({student.class} - {student.section})</div>
              <div className="entermarks-table-block" style={{ marginTop: 12 }}>
                <table className="entermarks-table">
                  <thead>
                    <tr>
                      <th>Subject</th>
                      <th>Category</th>
                      <th>Marks</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {marks.map((m) => (
                      <tr key={m._id}>
                        <td>{m.subject}</td>
                        <td>{m.category}</td>
                        <td>{m.marks}</td>
                        <td>{m.status || '-'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </section>
      </main>
    </div>
  );
}
